/**
 * `node docs/research/749-protect-last-lock/rosters.ts [--samples 30] [--from rosters.json]`: how often a trainer's
 * party carries Thrash, Petal Dance, Outrage or Raging Fury, by trainer class and wave, generated by the pinned game's
 * own party code (`rosters.test.ts.template`). Needs the provisioned pinned clone (in a worktree: link the main
 * checkout's .cache). Saves the raw rows next to this file.
 */
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";
import { suiteClone, suitePin, testInClone, vitestOn } from "../../../scripts/clone-test/clone-test.ts";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const { values: opt } = parseArgs({ options: { samples: { type: "string", default: "30" }, from: { type: "string" } } });

type Row = { cls: string; name: string; wave: number; parties: number; withLock: number; members: number; lockMembers: number; carriers: Record<string, number> };
type Out = { rows: Row[]; errors: string[]; errorCount: number; side: Record<string, number>; starters: number; wild: Record<string, { species: number; minLevel: number }> };

let data: Out;
if (opt.from) {
  data = JSON.parse(readFileSync(opt.from, "utf8"));
} else {
  const { out, output } = await testInClone({
    clone: suiteClone(),
    name: "rosters749",
    source: readFileSync(path.join(HERE, "rosters.test.ts.template"), "utf8"),
    env: { COACH_SAMPLES: opt.samples },
    echo: false,
    vitest: vitestOn(suitePin().pnpm),
  });
  if (!out) {
    console.error(output.split("\n").filter(l => /Error|FAIL|×|✓/.test(l)).slice(0, 40).join("\n"));
    process.exit(1);
  }
  data = JSON.parse(out);
  writeFileSync(path.join(HERE, "rosters.json"), JSON.stringify(data, null, 1));
}

const pct = (a: number, b: number) => (b ? `${Math.round((a / b) * 1000) / 10}%` : "–");
const byClass = new Map<string, Row[]>();
for (const r of data.rows) byClass.set(r.cls, [...(byClass.get(r.cls) ?? []), r]);

console.log("| Class | Types | Types that ever carry one | Parties with one | Members with one |");
console.log("| --- | --- | --- | --- | --- |");
for (const [cls, rows] of byClass) {
  const types = new Set(rows.map(r => r.name));
  const ever = new Set(rows.filter(r => r.withLock > 0).map(r => r.name));
  const sum = (k: "parties" | "withLock" | "members" | "lockMembers") => rows.reduce((t, r) => t + r[k], 0);
  console.log(`| ${cls} | ${types.size} | ${ever.size} | ${pct(sum("withLock"), sum("parties"))} | ${pct(sum("lockMembers"), sum("members"))} |`);
}

console.log("\n| Class | Wave | Parties with one |");
console.log("| --- | --- | --- |");
for (const [cls, rows] of byClass) {
  const waves = [...new Set(rows.map(r => r.wave))].sort((a, b) => a - b);
  for (const w of waves) {
    const at = rows.filter(r => r.wave === w);
    const p = at.reduce((t, r) => t + r.parties, 0), l = at.reduce((t, r) => t + r.withLock, 0);
    console.log(`| ${cls} | ${w} | ${pct(l, p)} |`);
  }
}

console.log("\nTrainer types that carry one, by share of parties (best wave), and who carries it:");
const best = new Map<string, Row>();
for (const r of data.rows) {
  if (!r.withLock) continue;
  const b = best.get(r.name);
  if (!b || r.withLock / r.parties > b.withLock / b.parties) best.set(r.name, r);
}
for (const r of [...best.values()].sort((a, b) => b.withLock / b.parties - a.withLock / a.parties)) {
  const waves = data.rows.filter(x => x.name === r.name && x.withLock).map(x => x.wave).join(", ");
  const who = Object.entries(r.carriers).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([k, n]) => `${k} ×${n}`).join("; ");
  console.log(`- ${r.cls} ${r.name}: ${pct(r.withLock, r.parties)} at W${r.wave} (seen at W${waves}) — ${who}`);
}

console.log("\nOur side (all species):", JSON.stringify(data.side), "starters:", data.starters);
console.log("Wild, by level-up learnset:", JSON.stringify(data.wild));
console.log(`Errors: ${data.errorCount}`, data.errors.slice(0, 5));
